 76 │ /// A handle to a running `tsc --api` session's JSON-RPC transport. Cheap to `Clone`
 77 │ /// (an `Arc` underneath) so multiple concurrent callers can share one connection.
 78 │ ///
 79 │ /// This is a raw request/response client, not a typed wrapper over TypeScript's
 80 │ /// checker methods — implementing the actual algorithm
 81 │ /// (`docs/type-checker-integration.md`, "The algorithm") is a separate, later pass;
 82 │ /// this crate only has to prove the transport and process lifecycle are sound.
 83 │ #[derive(Clone)]
 84 │ pub struct Client(Arc<ClientInner>);
 85 │ 
 86 │ impl Client {
 87 │     /// Spawns the background reader task over `stdout`. Returns the `Client` handle
 88 │     /// plus that task's `JoinHandle`, so a caller (the supervisor) can detect a crash
 89 │     /// independently of any single in-flight `request()` call — the reader task exits
 90 │     /// with the [`TscClientError`] that ended the session.
 91 │     pub(crate) fn connect(
 92 │         stdin: ChildStdin,
 93 │         stdout: ChildStdout,
 94 │         max_frame_bytes: usize,
 95 │     ) -> (Self, tokio::task::JoinHandle<TscClientError>) {
 96 │         let (notif_tx, notif_rx) = mpsc::unbounded_channel();
 97 │         let inner = Arc::new(ClientInner {
 98 │             stdin: AsyncMutex::new(stdin),
 99 │             pending: DashMap::new(),
100 │             next_id: AtomicU64::new(1),
101 │             next_seq: AtomicU64::new(1),
102 │             notifications: AsyncMutex::new(Some(notif_rx)),
103 │         });
104 │ 
105 │         let reader_inner = Arc::clone(&inner);
106 │         let handle = tokio::spawn(async move {
107 │             let mut framed = FramedRead::new(stdout, ContentLengthDecoder::new(max_frame_bytes));
108 │             let end = loop {
109 │                 match framed.next().await {
110 │                     Some(Ok(body)) => {
111 │                         let seq = reader_inner.next_seq.fetch_add(1, Ordering::SeqCst);
112 │                         reader_inner.dispatch(&body, seq, &notif_tx);
113 │                     }
114 │                     Some(Err(err)) => break err,
115 │                     // The decoder's `decode_eof` distinguishes a clean end (`Ok(None)`,
116 │                     // stream ends here) from an end mid-frame (`Err`, handled above) —
117 │                     // reaching `None` from the stream itself is always the clean case.
118 │                     None => break TscClientError::Crashed { status: None },
119 │                 }
120 │             };
121 │             reader_inner.fail_all_pending(&end);
122 │             end
123 │         });
124 │ 
125 │         (Client(inner), handle)
126 │     }
127 │ 
128 │     /// Sends a raw JSON-RPC request and awaits its response, or `Timeout` if `deadline`
129 │     /// elapses first. A response that arrives after the deadline is a no-op send into
130 │     /// a dropped receiver — it never gets attributed to a later, unrelated call.
131 │     pub async fn request(
132 │         &self,
133 │         method: &str,
134 │         params: serde_json::Value,
135 │         deadline: Duration,
136 │     ) -> Result<TaggedResponse, TscClientError> {
137 │         let id = self.0.next_id.fetch_add(1, Ordering::SeqCst);
138 │         let (tx, rx) = oneshot::channel();
139 │         self.0.pending.insert(id, tx);
140 │ 
141 │         let message = RequestMessage { id: RequestId(id), method: method.to_string(), params };
142 │         let body = match serde_json::to_vec(&message) {
143 │             Ok(body) => body,
144 │             Err(source) => {
145 │                 self.0.pending.remove(&id);
146 │                 return Err(TscClientError::Serialize(Arc::new(source)));
147 │             }
148 │         };
149 │ 
150 │         {
151 │             let mut stdin = self.0.stdin.lock().await;
152 │             if let Err(source) = transport::write_frame(&mut *stdin, &body).await {
153 │                 self.0.pending.remove(&id);
154 │                 return Err(TscClientError::Write(Arc::new(source)));
155 │             }
156 │         }
157 │ 
158 │         match tokio::time::timeout(deadline, rx).await {
159 │             Ok(Ok(result)) => result,
160 │             Ok(Err(_sender_dropped)) => Err(TscClientError::SessionClosed),
161 │             Err(_elapsed) => {
162 │                 self.0.pending.remove(&id);
163 │                 Err(TscClientError::Timeout { method: method.to_string(), after: deadline })
164 │             }
165 │         }
166 │     }
