168 │     /// Single-consumer: returns `Some` exactly once, `None` on every later call. Keeps
169 │     /// `Client` itself cheaply `Clone` without also fanning notifications out to every
170 │     /// clone.
171 │     pub fn take_notifications(&self) -> Option<mpsc::UnboundedReceiver<Notification>> {
172 │         self.0.notifications.try_lock().ok()?.take()
173 │     }
174 │ }
