52 │ /// Dispatches a decoded frame body by shape: an `id` alongside `result`/`error` is a
53 │ /// response to one of our requests; anything else with a `method` is a notification.
54 │ /// tsc --api never sends us a request of its own (no server-initiated calls in this
55 │ /// protocol), so those are the only two shapes handled.
56 │ pub fn parse_incoming(body: &[u8]) -> Result<IncomingMessage, serde_json::Error> {
57 │     let value: serde_json::Value = serde_json::from_slice(body)?;
58 │     let is_response = value.get("id").is_some() && (value.get("result").is_some() || value.get("error").is_some());
