 9 │ #![allow(dead_code)]
10 │ 
11 │ use camino::Utf8PathBuf;
12 │ use oxc_react_docgen_tsc_client::SupervisorConfig;
13 │ 
14 │ pub const PINNED_VERSION: &str = "7.1.0-test";
15 │ 
16 │ /// Returns the temp dir (kept alive for the caller's test duration) and a config ready
17 │ /// to `Supervisor::spawn`, with `FAKE_TSC_SCENARIO` set to `scenario`.
18 │ pub fn spawn_fake(scenario: &str) -> (tempfile::TempDir, SupervisorConfig) {
19 │     let dir = tempfile::tempdir().expect("create temp dir for fake-tsc layout");
20 │     let (tsc_path, cwd) = layout_with_version(&dir, PINNED_VERSION);
21 │     let mut config = SupervisorConfig::new(tsc_path, cwd, &[PINNED_VERSION]);
22 │     config.extra_env.push(("FAKE_TSC_SCENARIO".to_string(), scenario.to_string()));
23 │     (dir, config)
24 │ }
25 │ 
26 │ /// Builds the `node_modules/typescript/{package.json,bin/tsc}` layout with the given
27 │ /// version string and a copy of the real `fake-tsc` binary at `bin/tsc`. Returns
28 │ /// `(tsc_path, cwd)`.
29 │ pub fn layout_with_version(dir: &tempfile::TempDir, version: &str) -> (Utf8PathBuf, Utf8PathBuf) {
30 │     let typescript_dir = dir.path().join("node_modules").join("typescript");
31 │     let bin_dir = typescript_dir.join("bin");
32 │     std::fs::create_dir_all(&bin_dir).expect("create node_modules/typescript/bin");
33 │     std::fs::write(typescript_dir.join("package.json"), format!(r#"{{"version": "{version}"}}"#))
34 │         .expect("write package.json");
35 │ 
36 │     let fake_tsc_src = std::path::PathBuf::from(env!("CARGO_BIN_EXE_fake-tsc"));
37 │     let tsc_dest = bin_dir.join(if cfg!(windows) { "tsc.exe" } else { "tsc" });
38 │     std::fs::copy(&fake_tsc_src, &tsc_dest).expect("copy fake-tsc binary into place");
39 │ 
40 │     (
41 │         Utf8PathBuf::from_path_buf(tsc_dest).expect("temp path is UTF-8"),
42 │         Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).expect("temp path is UTF-8"),
43 │     )
44 │ }
45 │ 
46 │ /// Same layout, but without ever placing a binary at `bin/tsc` — for the missing-binary
47 │ /// case.
48 │ pub fn layout_without_binary(dir: &tempfile::TempDir, version: &str) -> (Utf8PathBuf, Utf8PathBuf) {
49 │     let typescript_dir = dir.path().join("node_modules").join("typescript");
50 │     std::fs::create_dir_all(&typescript_dir).expect("create node_modules/typescript");
51 │     std::fs::write(typescript_dir.join("package.json"), format!(r#"{{"version": "{version}"}}"#))
52 │         .expect("write package.json");
53 │     let tsc_path = typescript_dir.join("bin").join(if cfg!(windows) { "tsc.exe" } else { "tsc" });
54 │     (
55 │         Utf8PathBuf::from_path_buf(tsc_path).expect("temp path is UTF-8"),
56 │         Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).expect("temp path is UTF-8"),
57 │     )
58 │ }
