mod common;

use std::os::unix::fs::PermissionsExt;
use std::time::{Duration, Instant};

use camino::Utf8PathBuf;
use oxc_react_docgen_tsc_client::{Supervisor, SupervisorConfig, TscClientError};

fn sleeper_config(dir: &tempfile::TempDir) -> SupervisorConfig {
    let (tsc_path, cwd) = common::layout_with_version(dir, common::PINNED_VERSION);
    std::fs::write(&tsc_path, "#!/bin/sh\nexec sleep 30\n").unwrap();
    std::fs::set_permissions(&tsc_path, std::fs::Permissions::from_mode(0o755)).unwrap();
    SupervisorConfig::new(tsc_path, cwd, &[common::PINNED_VERSION])
}

#[tokio::test]
async fn adv_handshake_timeout_ignored() {
    let dir = tempfile::tempdir().unwrap();
    let mut config = sleeper_config(&dir);
    config.handshake_timeout = Duration::from_millis(20);
    let start = Instant::now();
    let supervisor = Supervisor::spawn(config).await;
    let elapsed = start.elapsed();
    tokio::time::sleep(Duration::from_millis(200)).await;
    let ok = supervisor.is_ok();
    let alive = supervisor.as_ref().map(|s| s.is_alive()).unwrap_or(false);
    eprintln!("ADV handshake: spawn ok={ok} alive_after_200ms={alive} spawn_elapsed={elapsed:?}");
    assert!(ok && alive);
    let mut s = supervisor.unwrap();
    let r = s.request("ping", serde_json::json!({}), Duration::from_millis(100)).await;
    eprintln!("ADV handshake: first request -> {r:?}; alive={}", s.is_alive());
    s.shutdown().await.unwrap();
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn adv_request_deadline_not_applied_to_write() {
    let dir = tempfile::tempdir().unwrap();
    let config = sleeper_config(&dir);
    let supervisor = Supervisor::spawn(config).await.unwrap();
    let client = supervisor.client();
    let big = "x".repeat(1 << 20);
    let c1 = client.clone();
    let big_req = tokio::spawn(async move {
        let start = Instant::now();
        let r = tokio::time::timeout(
            Duration::from_secs(3),
            c1.request("big", serde_json::json!({ "blob": big }), Duration::from_millis(200)),
        )
        .await;
        (r.is_err(), start.elapsed())
    });
    tokio::time::sleep(Duration::from_millis(100)).await;
    let start = Instant::now();
    let small = tokio::time::timeout(
        Duration::from_secs(3),
        client.request("small", serde_json::json!({}), Duration::from_millis(200)),
    )
    .await;
    let small_elapsed = start.elapsed();
    let (big_outer_elapsed, big_elapsed) = big_req.await.unwrap();
    eprintln!(
        "ADV write: big request hit outer 3s guard={big_outer_elapsed} after {big_elapsed:?} (deadline 200ms); \
         small request hit outer guard={} after {small_elapsed:?} (deadline 200ms)",
        small.is_err()
    );
    assert!(big_outer_elapsed && small.is_err());
    supervisor.shutdown().await.unwrap();
}

#[tokio::test]
async fn adv_crashed_status_always_none() {
    let (_dir, config) = common::spawn_fake("exit_after:1:3");
    let supervisor = Supervisor::spawn(config).await.unwrap();
    let client = supervisor.client();
    let _ = client.request("a", serde_json::json!({}), Duration::from_secs(2)).await;
    tokio::time::sleep(Duration::from_millis(200)).await;
    let r = client.request("b", serde_json::json!({}), Duration::from_secs(2)).await;
    eprintln!("ADV crashed: child exited with code 3; client saw {r:?}");
    if let Err(e) = &r {
        eprintln!("ADV crashed display: {e}");
    }
    assert!(matches!(r, Err(TscClientError::Crashed { status: None }) | Err(TscClientError::Write(_))));
    supervisor.shutdown().await.unwrap();
}

#[tokio::test(flavor = "multi_thread", worker_threads = 8)]
async fn adv_take_notifications_exactly_once_under_contention() {
    for _ in 0..30 {
        let (_dir, config) = common::spawn_fake("echo");
        let supervisor = Supervisor::spawn(config).await.unwrap();
        let client = supervisor.client();
        let barrier = std::sync::Arc::new(std::sync::Barrier::new(16));
        let handles: Vec<_> = (0..16)
            .map(|_| {
                let c = client.clone();
                let b = barrier.clone();
                std::thread::spawn(move || {
                    b.wait();
                    c.take_notifications().is_some()
                })
            })
            .collect();
        let somes = handles.into_iter().map(|h| h.join().unwrap()).filter(|x| *x).count();
        assert_eq!(somes, 1, "exactly one Some expected");
        supervisor.shutdown().await.unwrap();
    }
}

#[tokio::test]
async fn adv_real_tsc_notifications() {
    let repo = Utf8PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..").canonicalize_utf8().unwrap();
    let tsc_path = repo.join("apps/validate/node_modules/typescript-next/bin/tsc");
    let config = SupervisorConfig::new(tsc_path, repo.clone(), &["7.1.0-dev.20260926.1"]);
    let mut s = Supervisor::spawn(config).await.expect("spawn real tsc");
    let mut rx = s.client().take_notifications().unwrap();
    let init = s.request("initialize", serde_json::json!(null), Duration::from_secs(20)).await;
    eprintln!("ADV real: initialize -> {:?}", init.as_ref().map(|r| r.value.to_string().chars().take(200).collect::<String>()));
    let cfg = s
        .request(
            "parseConfigFile",
            serde_json::json!({ "file": repo.join("apps/validate/tsconfig.json").as_str() }),
            Duration::from_secs(20),
        )
        .await;
    eprintln!("ADV real: parseConfigFile -> {:?}", cfg.as_ref().map(|r| r.value.to_string().chars().take(120).collect::<String>()));
    let snap = s.request("updateSnapshot", serde_json::json!({ "openProject": repo.join("apps/validate/tsconfig.json").as_str() }), Duration::from_secs(60)).await;
    eprintln!("ADV real: updateSnapshot -> {:?}", snap.as_ref().map(|r| r.value.to_string().chars().take(200).collect::<String>()));
    let bogus = s.request("noSuchMethod", serde_json::json!({}), Duration::from_secs(5)).await;
    eprintln!("ADV real: bogus -> {bogus:?}");
    tokio::time::sleep(Duration::from_millis(1000)).await;
    let mut n = 0;
    while let Ok(note) = rx.try_recv() {
        n += 1;
        eprintln!("ADV real: notification {} {}", note.method, note.params);
    }
    eprintln!("ADV real: notifications received = {n}");
    s.shutdown().await.unwrap();
}

