fn sleeper_config(dir: &tempfile::TempDir) -> SupervisorConfig {
    let (tsc_path, cwd) = common::layout_with_version(dir, common::PINNED_VERSION);
    std::fs::write(&tsc_path, "#!/bin/sh\nexec sleep 30\n").unwrap();
    std::fs::set_permissions(&tsc_path, std::fs::Permissions::from_mode(0o755)).unwrap();
    SupervisorConfig::new(tsc_path, cwd, &[common::PINNED_VERSION])
}

