    let supervisor = Supervisor::spawn(config).await;
    let elapsed = start.elapsed();
    tokio::time::sleep(Duration::from_millis(200)).await;
    let ok = supervisor.is_ok();
    let alive = supervisor.as_ref().map(|s| s.is_alive()).unwrap_or(false);
    eprintln!("ADV handshake: spawn ok={ok} alive_after_200ms={alive} spawn_elapsed={elapsed:?}");
